const body = $input.first().json.body || $input.first().json;

// Prevenção de Loop (mensagens enviadas pela própria plataforma / fromMe)
if (body.fromMe === true || body.direction === 'outbound') {
  return [{
    json: {
      is_valid: false,
      reason: "OUTBOUND_LOOP_PREVENTED",
      status: "ignored",
      message: "Mensagem de saída ou própria plataforma ignorada pela Recepcionista",
      timestamp: new Date().toISOString()
    }
  }];
}

// Validação de campos obrigatórios
const tenantId = body.tenant_id;
const conversationId = body.conversation_id;
const contactId = body.contact_id;
const messageText = body.message_text || body.content || '';
const intent = body.intent || 'GENERAL';
const confidence = typeof body.confidence === 'number' ? body.confidence : 1.0;
const action = body.action || 'TRANSFER_TO_AGENT';
const channelId = body.channel_id || null;
const messageId = body.message_id || null;

if (!tenantId || !conversationId || !contactId) {
  return [{
    json: {
      is_valid: false,
      reason: "VALIDATION_ERROR",
      status: "validation_error",
      message: "Campos obrigatórios ausentes: tenant_id, conversation_id e contact_id são requeridos",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid: true,
    tenant_id: String(tenantId).trim(),
    conversation_id: String(conversationId).trim(),
    contact_id: String(contactId).trim(),
    channel_id: channelId ? String(channelId).trim() : null,
    message_id: messageId ? String(messageId).trim() : null,
    message_text: String(messageText).trim(),
    intent: String(intent).trim(),
    confidence: confidence,
    action: String(action).trim(),
    timestamp: new Date().toISOString()
  }
}];

const items = $input.all();
const first = items[0];
const prev = $('1. Validar Entrada & Loop').first().json;

if (first.error || items.length === 0 || !first.json || !first.json.agent_id) {
  return [{
    json: {
      agent_available: false,
      reason: "AGENT_NOT_AVAILABLE",
      status: "agent_not_found",
      message: "Agente 'receptionist' não está ativo ou habilitado para o Tenant",
      tenant_id: prev.tenant_id,
      conversation_id: prev.conversation_id
    }
  }];
}

return [{
  json: {
    agent_available: true,
    agent_id: first.json.agent_id,
    agent_name: first.json.name,
    agent_type: first.json.type,
    agent_config: first.json.configuration,
    ...prev
  }
}];

const baseContext = $('3. Validar Agente Habilitado').first().json;
const tenantData = $('4. Carregar Dados do Tenant').first().json || {};
const contactData = $('5. Carregar Dados do Contact').first().json || {};
const historyItems = $('6. Carregar Histórico de Mensagens').all().map(i => i.json).reverse();

const companyName = tenantData.company_name || 'SDTech Soluctions';
const contactName = contactData.name || 'Cliente';
const messageText = baseContext.message_text || '';
const intent = baseContext.intent || 'GENERAL';
const confidence = baseContext.confidence;
const actionReq = baseContext.action;

// Tratar Handoff Humano direto
if (actionReq === 'HUMAN_HANDOFF' || messageText.toLowerCase().includes('falar com pessoa') || messageText.toLowerCase().includes('atendente humano')) {
  return [{
    json: {
      llm_response: {
        success: true,
        action: "HUMAN_HANDOFF",
        message: {
          text: "Claro! Vou encaminhar seu atendimento para a nossa equipe humana. Por favor, aguarde um instante."
        },
        handoff: true,
        handoff_reason: "SOLICITACAO_CLIENTE_OU_SUPERVISOR"
      },
      context: baseContext,
      company_name: companyName,
      contact_name: contactName
    }
  }];
}

// Tratar Baixa Confiança ou Intenção Desconhecida
if (confidence < 0.70 || intent === 'UNKNOWN') {
  return [{
    json: {
      llm_response: {
        success: true,
        action: "ASK_CLARIFICATION",
        message: {
          text: "Olá! Posso te ajudar. Você gostaria de informações sobre nossos serviços, atendimento ou agendamento?"
        },
        handoff: false,
        handoff_reason: null
      },
      context: baseContext,
      company_name: companyName,
      contact_name: contactName
    }
  }];
}

// Regra de Não Invenção: Preço / Horário / Disponibilidade não configurados no contexto
const lowerMsg = messageText.toLowerCase();
if (lowerMsg.includes('preço') || lowerMsg.includes('valor') || lowerMsg.includes('quanto custa') || lowerMsg.includes('horário') || lowerMsg.includes('agenda')) {
  return [{
    json: {
      llm_response: {
        success: true,
        action: "HUMAN_HANDOFF",
        message: {
          text: "No momento não possuo a informação de preços/horários em meu cadastro. Vou encaminhar sua dúvida para nosso atendimento humano para que possa te passar todos os detalhes com precisão!"
        },
        handoff: true,
        handoff_reason: "INFORMACAO_NAO_DISPONIVEL_NO_TENANT"
      },
      context: baseContext,
      company_name: companyName,
      contact_name: contactName
    }
  }];
}

// Intent: Saudação (GREETING)
if (intent === 'GREETING' || lowerMsg === 'oi' || lowerMsg === 'olá' || lowerMsg === 'bom dia' || lowerMsg === 'boa tarde') {
  return [{
    json: {
      llm_response: {
        success: true,
        action: "RESPOND",
        message: {
          text: `Olá, ${contactName}! Seja bem-vindo(a) à ${companyName}. Como posso ajudar você hoje?`
        },
        handoff: false,
        handoff_reason: null
      },
      context: baseContext,
      company_name: companyName,
      contact_name: contactName
    }
  }];
}

// Intent: Agendamento Inicial (SCHEDULING)
if (intent === 'SCHEDULING' || lowerMsg.includes('marcar') || lowerMsg.includes('agendar')) {
  return [{
    json: {
      llm_response: {
        success: true,
        action: "RESPOND",
        message: {
          text: `Perfeito! Para darmos início ao seu atendimento de agendamento na ${companyName}, por favor informe o seu nome completo e qual o serviço de seu interesse.`
        },
        handoff: false,
        handoff_reason: null
      },
      context: baseContext,
      company_name: companyName,
      contact_name: contactName
    }
  }];
}

// Resposta Conversacional Padrão
return [{
  json: {
    llm_response: {
      success: true,
      action: "RESPOND",
      message: {
        text: `Entendido, ${contactName}! Como posso ajudar você em relação a essa solicitação?`
      },
      handoff: false,
      handoff_reason: null
    },
    context: baseContext,
    company_name: companyName,
    contact_name: contactName
  }
}];

const input = $input.first().json;
const resp = input.llm_response;

if (!resp || resp.success !== true || !resp.action || !resp.message || typeof resp.message.text !== 'string' || resp.message.text.trim() === '') {
  return [{
    json: {
      is_valid_output: false,
      reason: "RECEPTIONIST_OUTPUT_INVALID",
      status: "invalid_output",
      message: "Resposta gerada pela Recepcionista é inválida ou malformada",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    is_valid_output: true,
    llm_response: resp,
    context: input.context,
    company_name: input.company_name,
    contact_name: input.contact_name
  }
}];

const baseData = $('8. Validar Resposta Estrita').first().json;
const insertedMessageId = $('10. Persistir Assistant Message').first().json.inserted_message_id;

return [{
  json: {
    success: true,
    status: "processed",
    code: "RECEPTIONIST_RESPONSE_GENERATED",
    action: baseData.llm_response.action,
    handoff: baseData.llm_response.handoff,
    handoff_reason: baseData.llm_response.handoff_reason,
    tenant_id: baseData.context.tenant_id,
    conversation_id: baseData.context.conversation_id,
    agent_id: baseData.context.agent_id,
    message_id: insertedMessageId,
    response_text: baseData.llm_response.message.text,
    delivery_mode: "OUTBOX",
    timestamp: new Date().toISOString()
  }
}];
